def olcutler(TP, FP, FN, TN):
    P, N = TP + FN, FP + TN
    return {
        "secim": (TP + FP) / (P + N),
        "TPR": TP / P,
        "FPR": FP / N,
        "PPV": TP / (TP + FP),
    }

gruplar = {"Kuzey": (600, 200, 200, 1000), "Guney": (900, 300, 300, 500)}
d = {g: olcutler(*v) for g, v in gruplar.items()}

for g in gruplar:
    o = d[g]
    print(g, " ".join(f"{k}={round(o[k], 3)}" for k in ("secim", "TPR", "FPR", "PPV")))

for k in ("secim", "TPR", "FPR", "PPV"):
    fark = round(abs(d["Kuzey"][k] - d["Guney"][k]), 3)
    print(f"{k}: fark={fark} saglandi={fark <= 0.01}")

def isabet(yayginlik, duyarlilik, yanlis_alarm, n=10_000):
    sentetik = n * yayginlik
    gercek = n - sentetik
    dogru_alarm = sentetik * duyarlilik
    bos_alarm = gercek * yanlis_alarm
    return dogru_alarm, bos_alarm, dogru_alarm / (dogru_alarm + bos_alarm)

for y in (0.01, 0.05, 0.20):
    d, b, p = isabet(y, 0.92, 0.03)
    print(f"yayginlik={y:.2f} dogru={d:.0f} bos={b:.0f} isabet={p:.3f}")
